// The native post editor, part 1: what the other parts share (W), the server
// and the small helpers. Load order: write_core, write_editor, write_preview,
// write_live. Needs ui.js.
(function () {
  'use strict'

  var MNA = (window.MNA = window.MNA || {})
  var W = (MNA.write = {})

  W.ICONS = {"align-center": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><line x1=\"21\" x2=\"3\" y1=\"6\" y2=\"6\" />\n  <line x1=\"17\" x2=\"7\" y1=\"12\" y2=\"12\" />\n  <line x1=\"19\" x2=\"5\" y1=\"18\" y2=\"18\" /></svg>", "align-left": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><line x1=\"21\" x2=\"3\" y1=\"6\" y2=\"6\" />\n  <line x1=\"15\" x2=\"3\" y1=\"12\" y2=\"12\" />\n  <line x1=\"17\" x2=\"3\" y1=\"18\" y2=\"18\" /></svg>", "align-right": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><line x1=\"21\" x2=\"3\" y1=\"6\" y2=\"6\" />\n  <line x1=\"21\" x2=\"9\" y1=\"12\" y2=\"12\" />\n  <line x1=\"21\" x2=\"7\" y1=\"18\" y2=\"18\" /></svg>", "archive": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><rect width=\"20\" height=\"5\" x=\"2\" y=\"3\" rx=\"1\" />\n  <path d=\"M4 8v11a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8\" />\n  <path d=\"M10 12h4\" /></svg>", "bold": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M6 12h9a4 4 0 0 1 0 8H7a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h7a4 4 0 0 1 0 8\" /></svg>", "heading": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M6 12h12\" />\n  <path d=\"M6 20V4\" />\n  <path d=\"M18 20V4\" /></svg>", "heading-2": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M4 12h8\" />\n  <path d=\"M4 18V6\" />\n  <path d=\"M12 18V6\" />\n  <path d=\"M21 18h-4c0-4 4-3 4-6 0-1.5-2-2.5-4-1\" /></svg>", "heading-3": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M4 12h8\" />\n  <path d=\"M4 18V6\" />\n  <path d=\"M12 18V6\" />\n  <path d=\"M17.5 10.5c1.7-1 3.5 0 3.5 1.5a2 2 0 0 1-2 2\" />\n  <path d=\"M17 17.5c2 1.5 4 .3 4-1.5a2 2 0 0 0-2-2\" /></svg>", "heading-4": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M4 12h8\" />\n  <path d=\"M4 18V6\" />\n  <path d=\"M12 18V6\" />\n  <path d=\"M17 10v4h4\" />\n  <path d=\"M21 10v8\" /></svg>", "image": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><rect width=\"18\" height=\"18\" x=\"3\" y=\"3\" rx=\"2\" ry=\"2\" />\n  <circle cx=\"9\" cy=\"9\" r=\"2\" />\n  <path d=\"m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21\" /></svg>", "italic": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><line x1=\"19\" x2=\"10\" y1=\"4\" y2=\"4\" />\n  <line x1=\"14\" x2=\"5\" y1=\"20\" y2=\"20\" />\n  <line x1=\"15\" x2=\"9\" y1=\"4\" y2=\"20\" /></svg>", "link": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71\" />\n  <path d=\"M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71\" /></svg>", "list": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><line x1=\"8\" x2=\"21\" y1=\"6\" y2=\"6\" />\n  <line x1=\"8\" x2=\"21\" y1=\"12\" y2=\"12\" />\n  <line x1=\"8\" x2=\"21\" y1=\"18\" y2=\"18\" />\n  <line x1=\"3\" x2=\"3.01\" y1=\"6\" y2=\"6\" />\n  <line x1=\"3\" x2=\"3.01\" y1=\"12\" y2=\"12\" />\n  <line x1=\"3\" x2=\"3.01\" y1=\"18\" y2=\"18\" /></svg>", "list-ordered": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><line x1=\"10\" x2=\"21\" y1=\"6\" y2=\"6\" />\n  <line x1=\"10\" x2=\"21\" y1=\"12\" y2=\"12\" />\n  <line x1=\"10\" x2=\"21\" y1=\"18\" y2=\"18\" />\n  <path d=\"M4 6h1v4\" />\n  <path d=\"M4 10h2\" />\n  <path d=\"M6 18H4c0-1 2-2 2-3s-1-1.5-2-1\" /></svg>", "pilcrow": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M13 4v16\" />\n  <path d=\"M17 4v16\" />\n  <path d=\"M19 4H9.5a4.5 4.5 0 0 0 0 9H13\" /></svg>", "quote": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M16 3a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2 1 1 0 0 1 1 1v1a2 2 0 0 1-2 2 1 1 0 0 0-1 1v2a1 1 0 0 0 1 1 6 6 0 0 0 6-6V5a2 2 0 0 0-2-2z\" />\n  <path d=\"M5 3a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2 1 1 0 0 1 1 1v1a2 2 0 0 1-2 2 1 1 0 0 0-1 1v2a1 1 0 0 0 1 1 6 6 0 0 0 6-6V5a2 2 0 0 0-2-2z\" /></svg>", "save": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M15.2 3a2 2 0 0 1 1.4.6l3.8 3.8a2 2 0 0 1 .6 1.4V19a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z\" />\n  <path d=\"M17 21v-7a1 1 0 0 0-1-1H8a1 1 0 0 0-1 1v7\" />\n  <path d=\"M7 3v4a1 1 0 0 0 1 1h7\" /></svg>", "strikethrough": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M16 4H9a3 3 0 0 0-2.83 4\" />\n  <path d=\"M14 12a4 4 0 0 1 0 8H6\" />\n  <line x1=\"4\" x2=\"20\" y1=\"12\" y2=\"12\" /></svg>", "trash-2": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M3 6h18\" />\n  <path d=\"M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6\" />\n  <path d=\"M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2\" />\n  <line x1=\"10\" x2=\"10\" y1=\"11\" y2=\"17\" />\n  <line x1=\"14\" x2=\"14\" y1=\"11\" y2=\"17\" /></svg>", "underline": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M6 4v6a6 6 0 0 0 12 0V4\" />\n  <line x1=\"4\" x2=\"20\" y1=\"20\" y2=\"20\" /></svg>"}
  W.base = '/write'
  var POSTS = '/api/v2/document/Post'
  var UPLOAD = { optimize: '1', max_width: '1600', max_height: '1600' }
  var WORDS_PER_MINUTE = 200
  var EXCERPT_LENGTH = 140

  // What is on screen.
  W.state = {
    postId: null,
    loaded: false,
    status: 'Draft',
    savedAt: null,
    saving: null, // the status being saved
    coverRemoved: false,
    form: { title: '', post_type: 'Blog', attachment: '', images: [], cover_image: '', excerpt: '', display_title: '', tags: '' },
  }

  var listeners = {}
  W.on = function (name, callback) { (listeners[name] = listeners[name] || []).push(callback) }
  W.emit = function (name, payload) { (listeners[name] || []).forEach(function (callback) { callback(payload) }) }

  W.el = function (tag, className, text) { return MNA.el(tag, className, text) }

  W.icon = function (name, className) {
    var span = document.createElement('span')
    span.className = 'mna-w-icon ' + (className || '')
    span.innerHTML = (W.ICONS && W.ICONS[name]) || ''
    return span
  }

  W.isMobile = function () { return window.matchMedia('(max-width: 767px)').matches }

  // ---- Text helpers ----

  // Posts from before the rich editor are plain text with newlines.
  W.ensureHtml = function (raw) {
    if (!raw) return ''
    if (/<[a-z][\s\S]*>/i.test(raw)) return raw
    return raw.split(/\n{2,}/).map(function (part) { return '<p>' + escapeHtml(part.trim()).replace(/\n/g, '<br>') + '</p>' }).join('')
  }

  function escapeHtml(text) {
    return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  }

  W.plainText = function (html) {
    return (new DOMParser().parseFromString(html || '', 'text/html').body.textContent || '')
  }

  W.readTime = function (html) {
    var words = W.plainText(html).trim().split(/\s+/).filter(Boolean).length
    return Math.max(1, Math.round(words / WORDS_PER_MINUTE))
  }

  W.autoExcerpt = function (html) {
    var text = W.plainText(W.ensureHtml(html)).trim()
    return text.length > EXCERPT_LENGTH ? text.slice(0, EXCERPT_LENGTH) + '…' : text
  }

  W.firstImage = function (html) {
    var match = W.ensureHtml(html).match(/<img[^>]+src="([^"]+)"/)
    return match ? match[1].replace(/&amp;/g, '&') : ''
  }

  W.timeAgo = function (date) {
    var seconds = Math.floor((Date.now() - date.getTime()) / 1000)
    if (seconds < 30) return 'just now'
    if (seconds < 60) return seconds + 's ago'
    var minutes = Math.floor(seconds / 60)
    if (minutes < 60) return minutes + 'm ago'
    var hours = Math.floor(minutes / 60)
    if (hours < 24) return hours + 'h ago'
    return Math.floor(hours / 24) + 'd ago'
  }

  // ---- The server ----

  W.errorToast = function (error) { MNA.toast((error && error.message) || MNA.DEFAULT_ERROR) }

  W.load = function (id) { return MNA.request('GET', POSTS + '/' + encodeURIComponent(id)) }
  W.create = function (payload) { return MNA.request('POST', POSTS, payload) }
  W.update = function (id, payload) { return MNA.request('PUT', POSTS + '/' + encodeURIComponent(id), payload) }
  W.remove = function (id) { return MNA.request('DELETE', POSTS + '/' + encodeURIComponent(id)) }

  // Uploads a file and resolves with { file_url, file_name }. `options` are
  // extra form fields; pass {} for a file that is stored as it is.
  W.upload = function (file, options) {
    var form = new FormData()
    form.append('file', file, file.name)
    form.append('is_private', '1')
    var extra = options || UPLOAD
    Object.keys(extra).forEach(function (key) { form.append(key, extra[key]) })
    return fetch(location.origin + '/api/method/upload_file', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'X-Frappe-CSRF-Token': (window.frappe && window.frappe.csrf_token) || '' },
      body: form,
    }).then(function (response) {
      return response.json().catch(function () { return {} }).then(function (body) {
        if (!response.ok || !body.message) throw new Error('Error uploading ' + file.name)
        return { file_url: body.message.file_url, file_name: body.message.file_name }
      })
    })
  }
  W.uploadStory = function (file) { return W.upload(file, UPLOAD) }

  // ---- A small menu next to a button ----
  var openMenu = null
  function closeMenu() { if (openMenu) { openMenu.remove(); openMenu = null } }
  document.addEventListener('mousedown', function (event) { if (openMenu && !openMenu.contains(event.target) && !event.target.closest('[data-menu-anchor]')) closeMenu() })
  document.addEventListener('keydown', function (event) { if (event.key === 'Escape') closeMenu() })

  // items: { label, icon, onClick, danger, active }
  W.menu = function (anchor, items) {
    if (openMenu) { closeMenu(); return }
    var menu = W.el('div', 'mna-w-menu')
    anchor.setAttribute('data-menu-anchor', '')
    items.forEach(function (item) {
      var button = W.el('button', 'mna-w-menu-item' + (item.danger ? ' danger' : '') + (item.active ? ' active' : ''))
      button.type = 'button'
      button.appendChild(W.icon(item.icon, 'mna-w-small'))
      button.appendChild(W.el('span', '', item.label))
      // mousedown, so the editor keeps its selection until the command runs.
      button.addEventListener('mousedown', function (event) { event.preventDefault() })
      button.addEventListener('click', function () { closeMenu(); item.onClick() })
      menu.appendChild(button)
    })
    document.body.appendChild(menu)
    var rect = anchor.getBoundingClientRect()
    var width = menu.offsetWidth
    menu.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - width - 8)) + 'px'
    menu.style.top = Math.min(rect.bottom + 4, window.innerHeight - menu.offsetHeight - 8) + 'px'
    openMenu = menu
  }
  W.closeMenu = closeMenu
})()
